describe('RegistrarCuppingUseCase', () =&gt; {
  it('deve lancar erro se a nota final estiver fora do intervalo 0-100', () =&gt; {
    const repo = mockCafeRepository();
    const useCase = new RegistrarCuppingUseCase(repo);
    expect(() =&gt; useCase.executar({ cafeId: '1', notaFinal: 150 })).toThrow(NotaInvalidaException);
  });

  it('deve lancar erro se o cafe nao existir no repositorio', () =&gt; {
    const repo = mockCafeRepository({ existe: false });
    const useCase = new RegistrarCuppingUseCase(repo);
    expect(() =&gt; useCase.executar({ cafeId: 'inexistente', notaFinal: 85 })).toThrow(CafeNaoEncontradoException);
  });

  it('deve lancar erro se ja existir avaliacao do mesmo cafe na mesma data', () =&gt; {
    const repo = mockCafeRepository({ cuppingExistenteHoje: true });
    const useCase = new RegistrarCuppingUseCase(repo);
    expect(() =&gt; useCase.executar({ cafeId: '1', notaFinal: 85 })).toThrow(CuppingDuplicadoException);
  });
});

